int FileIo::Impl::switchMode(OpMode opMode) {
  if (opMode_ == opMode)
    return 0;
  OpMode oldOpMode = opMode_;
  opMode_ = opMode;

  bool reopen = true;
  switch (opMode) {
    case opRead:
      // Flush if current mode allows reading, else reopen (in mode "r+b"
      // as in this case we know that we can write to the file)
      if (openMode_.at(0) == 'r' || openMode_.at(1) == '+')
        reopen = false;
      break;
    case opWrite:
      // Flush if current mode allows writing, else reopen
      if (openMode_.at(0) != 'r' || openMode_.at(1) == '+')
        reopen = false;
      break;
    case opSeek:
      reopen = false;
      break;
  }

  if (!reopen) {
    // Don't do anything when switching _from_ opSeek mode; we
    // flush when switching _to_ opSeek.
    if (oldOpMode == opSeek)
      return 0;

    // Flush. On msvcrt fflush does not do the job
    std::fseek(fp_, 0, SEEK_CUR);
    return 0;
  }

  // Reopen the file
  long offset = std::ftell(fp_);
  if (offset == -1)
    return -1;
  // 'Manual' open("r+b") to avoid munmap()
  if (fp_) {
    std::fclose(fp_);
    fp_ = nullptr;
  }
  openMode_ = "r+b";
  opMode_ = opSeek;
  fp_ = std::fopen(path_.c_str(), openMode_.c_str());
  if (!fp_)
    return 1;
  return std::fseek(fp_, offset, SEEK_SET);
}  // FileIo::Impl::switchMode

int FileIo::Impl::stat(StructStat& buf) const {
  int ret = 0;
  struct stat st;
  ret = ::stat(path_.c_str(), &st);
  if (0 == ret) {
    buf.st_size = st.st_size;
    buf.st_mode = st.st_mode;
  }
  return ret;
}  // FileIo::Impl::stat

FileIo::FileIo(const std::string& path) : p_(std::make_unique<Impl>(path)) {
}

FileIo::~FileIo() {
  close();
